command:
/**
 * SVA example: Spike Trap (10 ft)
 * Springs a spike trap on one or more tiles; run it again to re-arm the trap.
 *
 * Setup: place a Tile (any image, for example the hidden spike-trap still frame of JB2A)
 * the size of the trap. Then EITHER select the tile(s) before running this macro,
 * OR tag them once so the macro finds them without selection (run in the console with the tile selected):
 *   canvas.tiles.controlled[0].document.setFlag("world", "svaTag", "spike-trap")
 * Tokens standing on the trap when it springs get a blood splash.
 *
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer or Tagger needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const TAG = "spike-trap";
const FILES = {
  spring: "jb2a.spike_trap.10x10ft.top.no_base.normal.01",
  deployed: "jb2a.spike_trap.10x10ft.top.no_base.still_frame.deployed",
  rearm: "jb2a.spike_trap.10x10ft.top.no_base.rearming.01",
  blood: "jb2a.liquid.splash.red"
};

const tiles = canvas.tiles.controlled.length
  ? canvas.tiles.controlled
  : canvas.tiles.placeables.filter((t) => t.document.getFlag("world", "svaTag") === TAG);
if (!tiles.length) return ui.notifications.warn("Select a trap tile, or tag one with the 'spike-trap' flag.");

const sceneId = canvas.scene.id;
await SVA.net.preload(Object.values(FILES));

for (const tile of tiles) {
  const { x, y, width, height } = tile.document;
  const center = { x: x + width / 2, y: y + height / 2 };
  const stateName = `${TAG}:${tile.id}`;
  const isDeployed = SVA.effects.list({ sceneId, name: stateName }).length > 0;
  const seq = SVA.sequence();

  if (isDeployed) {
    // Re-arm: play the retracting spikes, then drop the stored "deployed" frame underneath.
    seq.effect().file(FILES.rearm).atLocation(center).size(width, height).layer("belowTokens").zIndex(2);
    seq.wait(500);
    await seq.play();
    await SVA.effects.end({ name: stateName, sceneId });
    continue;
  }

  // Splash whoever stands on the tile as the spikes come out (delayed, does not block the sequence).
  const victims = canvas.tokens.placeables.filter((t) => {
    const c = t.center;
    return c.x >= x && c.x <= x + width && c.y >= y && c.y <= y + height;
  });
  for (const victim of victims) {
    seq
      .effect()
      .file(FILES.blood)
      .atLocation(victim)
      .scaleToObject(1.4)
      .rotate(Math.random() * 360)
      .delay(350);
  }
  // Spring the trap, then keep the deployed spikes on the tile until the next run.
  seq
    .effect()
    .file(FILES.spring)
    .atLocation(center)
    .size(width, height)
    .layer("belowTokens")
    .zIndex(2)
    .fadeOut(300)
    .waitUntilFinished(-2600);
  seq
    .effect()
    .file(FILES.deployed)
    .atLocation(center)
    .size(width, height)
    .layer("belowTokens")
    .zIndex(1)
    .fadeIn(200)
    .persist(true)
    .name(stateName);
  await seq.play();
}
